  "summary": "SDL（Simple DirectMedia Layer）是一个用 C 语言编写的跨平台多媒体库，为游戏、模拟器及多媒体应用提供统一的底层硬件抽象。其设计目标是让开发者用一套代码即可在 Windows、macOS、Linux、iOS、Android 及各类游戏主机上实现图形渲染、音频播放、用户输入处理、窗口管理等核心功能，无需针对每个平台单独适配——从而大幅降低跨平台多媒体应用的开发门槛。",
  "categories": [
    {
      "name": "视频与图形子系统",
      "description": "窗口创建与管理、2D 渲染（OpenGL/OpenGL ES/Direct3D 9/11/12/Metal/Vulkan/软件渲染器）、GPU 底层 3D 图形与计算 API（跨 Metal/Vulkan/D3D12 的统一抽象）、像素格式转换、表面操作与混合",
      "evidence": ["include/SDL3/SDL_video.h", "include/SDL3/SDL_render.h", "include/SDL3/SDL_gpu.h", "include/SDL3/SDL_surface.h", "src/video/", "src/render/", "src/gpu/"]
    },
    {
      "name": "音频子系统",
      "description": "音频设备枚举与管理、音频流播放与录制（SDL_AudioStream 管线）、格式转换与重采样、WAV 文件加载；后端覆盖 WASAPI/DirectSound/CoreAudio/ALSA/PulseAudio/PipeWire/JACK/sndio 等",
      "evidence": ["include/SDL3/SDL_audio.h", "src/audio/", "src/audio/wasapi/", "src/audio/coreaudio/", "src/audio/alsa/", "src/audio/pulseaudio/"]
    },
    {
      "name": "输入子系统",
      "description": "键盘、鼠标、触摸屏、游戏手柄/摇杆/力反馈的统一抽象；支持 Xbox/PlayStation/Nintendo 等主流手柄协议（包括 HID/USB/蓝牙）；触控与触控笔（SDL_Pen）；力反馈（haptic）",
      "evidence": ["include/SDL3/SDL_gamepad.h", "include/SDL3/SDL_joystick.h", "include/SDL3/SDL_haptic.h", "include/SDL3/SDL_keyboard.h", "include/SDL3/SDL_mouse.h", "include/SDL3/SDL_pen.h", "src/joystick/", "src/haptic/", "src/hidapi/"]
    },
    {
      "name": "系统与 IO 抽象",
      "description": "跨平台文件系统访问、异步 IO (SDL_AsyncIO)、线程与同步原语、原子操作、定时器、剪贴板、消息对话框、系统托盘图标、通知推送、传感器数据（加速度计/陀螺仪等）、摄像头与电源管理",
      "evidence": ["include/SDL3/SDL_iostream.h", "include/SDL3/SDL_asyncio.h", "include/SDL3/SDL_thread.h", "include/SDL3/SDL_mutex.h", "include/SDL3/SDL_clipboard.h", "include/SDL3/SDL_system.h", "src/core/", "src/thread/", "src/filesystem/", "src/power/", "src/sensor/", "src/camera/"]
    },
    {
      "name": "跨平台构建与基础设施",
      "description": "CMake 构建系统支持 via CMakeLists.txt；通过平台编译宏（#ifdef _WIN32/__APPLE__/__linux__）为每个平台编译不同的后端实现；动态 API 加载（SDL_dynapi 允许运行时覆盖函数指针）",
      "evidence": ["CMakeLists.txt", "cmake/sdlchecks.cmake", "cmake/sdlplatform.cmake", "src/dynapi/", "VisualC/", "Xcode/"]
    }
  ],
  "domain": "多媒体/游戏开发",
  "target_users": "游戏开发者、跨平台桌面/移动应用开发者、模拟器及多媒体工具开发者",
  "ecosystem": "cpp"
}
